import { useSearchParams } from 'react-router-dom';
import { BrowserRouter } from 'react-router-dom';

const QUESTS = [
  { id: 1, title: 'Slay the Dragon', status: 'active' },
  { id: 2, title: 'Recover the Tome', status: 'completed' },
  { id: 3, title: 'Find the Lost Mage', status: 'active' },
];

function QuestBoard() {
  const [searchParams, setSearchParams] = useSearchParams();
  const filter = searchParams.get('filter') ?? 'all';
  const q = searchParams.get('q') ?? '';

  const visible = QUESTS
    .filter(quest => filter === 'all' || quest.status === filter)
    .filter(quest => quest.title.toLowerCase().includes(q.toLowerCase()));

  function setFilter(f) {
    setSearchParams(prev => { prev.set('filter', f); return prev; });
  }

  function setSearch(s) {
    setSearchParams(prev => { prev.set('q', s); return prev; });
  }

  return (
    <div>
      <input value={q} onChange={e => setSearch(e.target.value)} data-testid="search-input" />
      <button onClick={() => setFilter('all')} data-testid="filter-all">All</button>
      <button onClick={() => setFilter('active')} data-testid="filter-active">Active</button>
      <p data-testid="filter-value">{filter}</p>
      <p data-testid="search-value">{q}</p>
      <ul>
        {visible.map(q => <li key={q.id}>{q.title}</li>)}
      </ul>
    </div>
  );
}

export default function App() {
  return <BrowserRouter><QuestBoard /></BrowserRouter>;
}
